import { useQuery } from "@tanstack/react-query";
import { loadReceiptMetadata } from "../../api";
import { RECEIPT_METADATA_STALE_TIME, RECEIPTS_QUERY_KEYS } from "../../constants";
export default function useReceiptMetadataQuery() {
    return useQuery({
        queryKey: RECEIPTS_QUERY_KEYS.metadata,
        queryFn: ({ signal }) => loadReceiptMetadata(signal),
        staleTime: RECEIPT_METADATA_STALE_TIME
    });
}
