import { SortT } from "../types";
function normalizeSearchValue(value, locale) {
    const searchValue = typeof value === "string" ? value : "";
    return searchValue
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .toLocaleLowerCase(locale)
        .trim();
}
export function filterReceipts(receipts, query, locale) {
    const normalizedQuery = normalizeSearchValue(query || "", locale);
    if (!normalizedQuery)
        return receipts;
    return receipts.filter((receipt) => (normalizeSearchValue(receipt.shopName, locale).includes(normalizedQuery)
        || normalizeSearchValue(receipt.address, locale).includes(normalizedQuery)));
}
export function filterProducts(products, query, locale) {
    const normalizedQuery = normalizeSearchValue(query || "", locale);
    if (!normalizedQuery)
        return products;
    return products.filter((product) => (normalizeSearchValue(product.name, locale).includes(normalizedQuery)));
}
export function sortProducts(products, sort) {
    const direction = sort === SortT.PriceAsc ? 1 : -1;
    return products.slice().sort((a, b) => {
        if (!a.currency && !b.currency)
            return 0;
        if (!a.currency)
            return 1;
        if (!b.currency)
            return -1;
        return (a.totalPrice - b.totalPrice) * direction;
    });
}
