    /* Surfaces */
    --app-bg: #f7f9f8;
    --surface: #ffffff;
    --surface-secondary: #f4f6f5;
    --surface-disabled: #eef1f0;
    --table-header-bg: #f6f8f7;
    --table-row-hover: #f1f8f4;
    --modal-backdrop: rgba(15, 23, 42, 0.52);
    --surface-overlay-strong: rgba(7, 13, 24, 0.94);
    --surface-overlay-control: rgba(255, 255, 255, 0.12);
    --surface-overlay-control-hover: rgba(255, 255, 255, 0.2);

    /* Shadows */
    --shadow-color-card: rgba(16, 24, 40, 0.06);
    --shadow-color-dropdown: rgba(16, 24, 40, 0.12);
    --shadow-color-magnifier-outline: rgba(16, 24, 40, 0.16);
    --shadow-color-zoom-hint: rgba(16, 24, 40, 0.18);
    --shadow-color-modal: rgba(16, 24, 40, 0.22);
    --shadow-color-magnifier: rgba(16, 24, 40, 0.32);

    /* Text */
    --text-primary: #101828;
    --text-secondary: #344054;
    --text-muted: #667085;
    --text-placeholder: #98a2b3;
    --text-disabled: #a7afb9;
    --text-on-accent: #ffffff;
    --link-hover: #05633c;

    /* Borders */
    --border-default: #dde3e0;
    --border-subtle: #eaeeec;
    --border-control: #d0d7d4;
    --border-control-hover: #aebbb5;
    --border-control-active: #98a49e;
    --border-disabled: #e3e7e5;
    --table-divider: #e7ebe9;
    --border-on-dark: rgba(255, 255, 255, 0.24);
    --border-magnifier: rgba(255, 255, 255, 0.94);

    /* Primary */
    --primary: #159455;
    --primary-hover: #107a46;
    --primary-active: #0b653a;
    --primary-disabled: #91c9aa;
    --primary-soft: #e7f6ee;
    --primary-soft-hover: #d8f0e3;
    --primary-border: #b9e4cc;
    --primary-text: #087a4b;
    --primary-focus: rgba(21, 148, 85, 0.22);

    /* Danger */
    --danger: #e52f3e;
    --danger-hover: #c92332;
    --danger-active: #a91d2a;
    --danger-soft: #fdebed;
    --danger-soft-hover: #fadadd;
    --danger-border: #f5b8be;
    --danger-text: #d62837;
    --danger-focus: rgba(229, 47, 62, 0.2);

    /* Status */
    --success-soft: #ddf4e8;
    --neutral-soft: #eef1f3;
    --neutral-status-text: #475467;
    --warning-soft: #fff3d6;
    --warning-text: #9a6700;

    /* Authentication */
    --auth-shadow-soft: rgba(0, 0, 0, 0.1);
    --auth-shadow-medium: rgba(0, 0, 0, 0.15);
    --auth-shadow-strong: rgba(0, 0, 0, 0.2);

    /* Bootstrap color aliases */
    --bs-body-color: var(--text-secondary);
    --bs-body-bg: var(--app-bg);
    --bs-primary: var(--primary);
    --bs-primary-rgb: 21, 148, 85;
    --bs-danger: var(--danger);
    --bs-danger-rgb: 229, 47, 62;
    --bs-border-color: var(--border-default);
}
