import { useMutation } from "@tanstack/react-query";
import { updateReceipt } from "../../api";
import useReceiptsCache from "../useReceiptsCache";
export default function useUpdateReceiptMutation() {
    const cache = useReceiptsCache();
    return useMutation({
        mutationFn: ({ id, receipt }) => (updateReceipt(id, receipt)),
        onSuccess: ({ updatedDescriptions, updatedReceipt }) => {
            cache.upsertReceipt(updatedReceipt);
            if (updatedDescriptions && Object.keys(updatedDescriptions).length) {
                cache.updateDescriptions(updatedDescriptions);
            }
            void cache.invalidateMetadata();
        }
    });
}
