import { useEffect, useState } from "react";
import { useQueryClient } from "@tanstack/react-query";
import { useNavigate } from "react-router-dom";
import { checkAuthRequest, loginRequest } from "../../api";
import { TOKEN_NAME } from "../../../../constants";
import Storage from "../../../../utils/Storage";
export default function useAuthController() {
    const [isLoading, setIsLoading] = useState(true);
    const [isAuthenticated, setIsAuthenticated] = useState(false);
    const [googleUserInfo, setGoogleUserInfo] = useState(null);
    const navigate = useNavigate();
    const queryClient = useQueryClient();
    useEffect(() => {
        async function checkLogin() {
            try {
                setIsLoading(true);
                // const googleUserInfoRes = await getGoogleUserInfoRequest();
                // const userInfo = await googleUserInfoRes.json();
                // if (userInfo && userInfo.user) {
                //     setGoogleUserInfo(userInfo.user);
                //     setIsLoading(false);
                //     return;
                // }
                const checkAuthDataRes = await checkAuthRequest();
                const checkAuthData = await checkAuthDataRes.json();
                setIsAuthenticated(checkAuthData.isAuthenticated);
                setIsLoading(false);
            }
            catch (error) {
                console.error("Auth check failed:", error);
                setIsAuthenticated(false);
                setIsLoading(false);
            }
        }
        checkLogin();
    }, []);
    const login = async (username, password) => {
        try {
            setIsLoading(true);
            const response = await loginRequest(username, password);
            const data = await response.json();
            if (response.ok) {
                if (data.token) {
                    queryClient.clear();
                    Storage.set(TOKEN_NAME, data.token);
                    setIsAuthenticated(true);
                    setIsLoading(false);
                    navigate("/", { replace: true });
                }
            }
            else {
                setIsLoading(false);
                throw new Error(data.message || "Login failed");
            }
        }
        catch (error) {
            console.error("Login error:", error);
            setIsAuthenticated(false);
            setIsLoading(false);
        }
    };
    const logout = () => {
        try {
            queryClient.clear();
            Storage.remove(TOKEN_NAME);
            navigate("/login", { replace: true });
        }
        catch (error) {
            console.error("Logout error:", error);
        }
        finally {
            setIsAuthenticated(false);
        }
    };
    return {
        isLoading,
        isAuthenticated,
        googleUserInfo,
        login,
        logout,
        setGoogleUserInfo
    };
}
