export function getReceiptId(receipt) {
    return receipt._id || receipt.id;
}
export function calculateReceiptItemTotal(items) {
    return items.reduce((total, item) => total + Math.round(item.price * 100), 0) / 100;
}
export function hasMatchingTotal(receipt) {
    return Math.round(calculateReceiptItemTotal(receipt.items) * 100)
        === Math.round(receipt.totalPrice * 100);
}
