import { TOKEN_NAME } from "../../../constants";
import Storage from "../../../utils/Storage";
const SERVER_URL = process.env.NODE_ENV === "production"
    ? process.env.SERVER_URL_PROD
    : process.env.SERVER_URL_DEV;
function getAuthToken() {
    return Storage.get(TOKEN_NAME);
}
function getEarliestReceiptRequest(signal) {
    const token = getAuthToken();
    return fetch(`${SERVER_URL}/api/get-earliest-receipt`, {
        signal,
        headers: {
            "Authorization": `Bearer ${token}`
        }
    });
}
function getReceiptsInDateRangeRequest(startDate, endDate, signal) {
    const token = getAuthToken();
    return fetch(`${SERVER_URL}/api/get-receipts-in-date-range?startDate=${startDate}&endDate=${endDate}`, {
        signal,
        headers: {
            "Authorization": `Bearer ${token}`
        }
    });
}
function fetchReceiptImageRequest(id, signal) {
    const token = getAuthToken();
    return fetch(`${SERVER_URL}/api/receipt-image/${id}`, {
        signal,
        headers: {
            "Authorization": `Bearer ${token}`
        }
    });
}
function deleteReceiptRequest(id) {
    const token = getAuthToken();
    return fetch(`${SERVER_URL}/api/delete-receipt/${id}`, {
        method: "DELETE",
        headers: {
            "Authorization": `Bearer ${token}`
        }
    });
}
function updateReceiptRequest(id, updatedData) {
    const token = getAuthToken();
    return fetch(`${SERVER_URL}/api/update-receipt/${id}`, {
        method: "PUT",
        body: JSON.stringify(updatedData),
        headers: {
            "Authorization": `Bearer ${token}`,
            "Content-Type": "application/json"
        }
    });
}
function getReceiptDescriptionsRequest(signal) {
    const token = getAuthToken();
    return fetch(`${SERVER_URL}/api/get-descriptions`, {
        signal,
        headers: {
            "Authorization": `Bearer ${token}`
        }
    });
}
export async function loadReceipts({ endDate, signal, startDate }) {
    if (!startDate || !endDate)
        return [];
    const response = await getReceiptsInDateRangeRequest(startDate, endDate, signal);
    if (!response.ok)
        throw new Error("Failed to load receipts");
    const data = await response.json();
    return data.receipts;
}
export async function loadReceiptMetadata(signal) {
    const [rangeResponse, descriptionsResponse] = await Promise.all([
        getEarliestReceiptRequest(signal),
        getReceiptDescriptionsRequest(signal)
    ]);
    if (!rangeResponse.ok || !descriptionsResponse.ok) {
        throw new Error("Failed to load receipt metadata");
    }
    const range = await rangeResponse.json();
    const receiptDescriptions = await descriptionsResponse.json();
    return {
        descriptions: receiptDescriptions.descriptions || {},
        earliestReceipt: range.earliest || null,
        latestReceipt: range.latest || null
    };
}
export async function loadReceiptImage(id, signal) {
    const response = await fetchReceiptImageRequest(id, signal);
    if (!response.ok)
        throw new Error("Failed to load receipt file");
    return response.blob();
}
export async function removeReceipt(id) {
    const response = await deleteReceiptRequest(id);
    if (!response.ok)
        throw new Error("Failed to delete receipt");
}
export async function updateReceipt(id, updatedData) {
    const response = await updateReceiptRequest(id, updatedData);
    if (!response.ok)
        throw new Error("Failed to update receipt");
    return response.json();
}
