import { useCallback, useState } from "react";
import useDeleteReceiptMutation from "../useDeleteReceiptMutation";
export default function useReceiptDeletion({ onDeleted, receiptId }) {
    const [isDeleteOpen, setIsDeleteOpen] = useState(false);
    const { isError: hasDeleteError, isPending: isDeleting, mutateAsync: deleteReceipt, reset: resetDelete } = useDeleteReceiptMutation();
    const confirmDelete = useCallback(async () => {
        if (!receiptId || isDeleting)
            return;
        resetDelete();
        try {
            await deleteReceipt(receiptId);
            setIsDeleteOpen(false);
            onDeleted(receiptId);
        }
        catch (error) {
            console.error(error);
        }
    }, [deleteReceipt, isDeleting, onDeleted, receiptId, resetDelete]);
    const closeDeleteDialog = useCallback(() => {
        setIsDeleteOpen(false);
        resetDelete();
    }, [resetDelete]);
    const openDeleteDialog = useCallback(() => {
        resetDelete();
        setIsDeleteOpen(true);
    }, [resetDelete]);
    return {
        closeDeleteDialog,
        confirmDelete,
        hasDeleteError,
        isDeleteOpen,
        isDeleting,
        openDeleteDialog
    };
}
