import { useQuery } from "@tanstack/react-query";
import { loadReceipts } from "../../api";
import { RECEIPTS_QUERY_KEYS, RECEIPTS_STALE_TIME } from "../../constants";
export default function useReceiptsQuery({ endDate, startDate }) {
    const isValidRange = Boolean(startDate && endDate && startDate <= endDate);
    return useQuery({
        enabled: isValidRange,
        queryKey: RECEIPTS_QUERY_KEYS.list(startDate, endDate),
        queryFn: ({ signal }) => loadReceipts({ endDate, signal, startDate }),
        staleTime: RECEIPTS_STALE_TIME
    });
}
