import { useQuery } from "@tanstack/react-query";
import { loadReceiptImage } from "../../api";
import { RECEIPTS_QUERY_KEYS } from "../../constants";
export default function useReceiptImageQuery(receiptImageId) {
    return useQuery({
        enabled: Boolean(receiptImageId),
        queryKey: RECEIPTS_QUERY_KEYS.image(receiptImageId || "missing"),
        queryFn: ({ signal }) => loadReceiptImage(receiptImageId, signal),
        staleTime: Infinity
    });
}
