import { useMutation } from "@tanstack/react-query";
import { removeReceipt } from "../../api";
import useReceiptsCache from "../useReceiptsCache";
export default function useDeleteReceiptMutation() {
    const cache = useReceiptsCache();
    return useMutation({
        mutationFn: (receiptId) => removeReceipt(receiptId),
        onSuccess: (_, receiptId) => {
            cache.removeReceipt(receiptId);
            void cache.invalidateMetadata();
        }
    });
}
