import { useCallback, useMemo } from "react";
import { useParams } from "react-router-dom";
import { getReceiptId } from "../../utils/receipts";
import useReceipts from "../useReceipts";
import useReceiptDeletion from "../useReceiptDeletion";
import useReceiptEditSession from "../useReceiptEditSession";
import useReceiptNavigationGuard from "../useReceiptNavigationGuard";
export default function useReceiptDetailsController() {
    const { receipts, descriptions, isLoading, hasError: hasLoadError, retry } = useReceipts();
    const { receiptId } = useParams();
    const receipt = useMemo(() => receipts.find((item) => getReceiptId(item) === receiptId), [receiptId, receipts]);
    const { discardEdit, ...editSession } = useReceiptEditSession({
        descriptions,
        receipt
    });
    const navigation = useReceiptNavigationGuard({
        isDirty: editSession.isDirty,
        onDiscard: discardEdit
    });
    const handleDeleted = useCallback(() => {
        navigation.navigateToReceipts("receiptDeleted");
    }, [navigation.navigateToReceipts]);
    const deletion = useReceiptDeletion({ onDeleted: handleDeleted, receiptId });
    return {
        descriptions,
        hasLoadError,
        isLoading,
        receipt,
        retry,
        ...editSession,
        ...navigation,
        ...deletion
    };
}
